<?php
namespace qqworld_collector\module\collect_filter; class insert_by_characters extends filter { public function by_characters($item, $position, $content) { $preg = preg_match_all("/[\x01-\x7f]|[\xe0-\xef][\x80-\xbf]{2}/", $item, $matches); if ($preg) { $allow = true; $results = array(); $count = 0; foreach ($matches[0] as $index => &$match) { if ($match == '<' || $match == '[') { $allow = false; $results[] = array( 'c' => $match, 'p' => '-' ); continue; } elseif ($match == '>' || $match == ']') { $allow = true; $results[] = array( 'c' => $match, 'p' => '-' ); continue; } $results[] = array( 'c' => $match, 'p' => $allow ? ++$count : '-' ); } if (preg_match('/(\d*)\%/', $position, $match)) $position = intval($count * $match[1] / 100); $found_key = array_search($position, array_column($results, 'p')); $results[$found_key]['c'] .= $content; $results = array_column($results, 'c'); $item = implode('', $results); } return $item; } public function by_paragraphs($item, $position, $content) { if (strstr($item, '</p>') !== false) { $preg = preg_match_all('/<p.*?>[\s\S]*?<\/p>/i', $item, $matches); if ($preg) { if (preg_match('/(\d*)\%/', $position, $match)) $position = intval(count($matches[0]) * $match[1] / 100); if ($position) $position--; $item = str_replace($matches[0][$position], $matches[0][$position].$content, $item, 1); } } else { $preg = preg_match_all('/.*?\r?\n/i', $item, $matches); if ($preg) { if (preg_match('/(\d*)\%/', $position, $match)) $position = intval(count($matches[0]) * $match[1] / 100); if ($position) $position--; $item = @str_replace($matches[0][$position], $matches[0][$position].$content, $item); } } return $item; } public function filter($item, $args, $source_link, $html, $type, $item_args, $download_args, $mode) { if (!empty($args)) { extract($args); $content = apply_filters( 'qqworld-collector-collection-project-variable-filter', $content, 0 ); switch ($type) { case 'characters': $item = $this->by_characters($item, $position, $content); break; case 'paragraphs': $item = $this->by_paragraphs($item, $position, $content); break; } } return $item; } } ?>